rows, cols = input().split()
grid = []
for r in range(int(rows)):
    grid.append(["."] * int(cols))
while True:
    line = input()
    if line == "end":
        break
    r, c = line.split()
    grid[int(r) - 1][int(c) - 1] = "#"
for row in grid:
    print("".join(row))

items = []
history = []
while True:
    line = input()
    if line == "end":
        break
    if line == "show":
        print(items)
    elif line == "undo":
        if len(history) > 0:
            items = history.pop()
    else:
        history.append(items[:])
        if line == "sort":
            items.sort()
        elif line == "clear":
            items = []
        else:
            items.append(line[4:])

